def assertRaises(func, args, kwargs, expected_exception, expected_message):
    """
        Assert that the expected exception is raised when calling a
        function, and that the right error message is included with
        that exception.

        Arguments:
          func -- the function to call
          args -- positional arguments to `func`
          kwargs -- keyword arguments to `func`
          expected_exception -- exception that should be raised
          expected_message -- expected exception message (or pattern
            if a compiled regex object)

        Returns the exception raised for further testing.
        """
    if args is None:
        args = ()
    if kwargs is None:
        kwargs = {}
    try:
        func(*args, **kwargs)
    except expected_exception as err:
        actual_message = str(err)
        if isinstance(expected_message, re.Pattern):
            assert expected_message.search(actual_message), ('assertTrue', expected_message.search(actual_message))
        else:
            assert actual_message == expected_message, ('assertEqual', actual_message, expected_message)
        return err
    else:
        raise AssertionError('expected exception %(expected_exception)s not raised\ncalled %(func)r\nwith args %(args)r\nand kwargs %(kwargs)r\n' % locals())

def assertTypeError(func, expected_message, *args):
